-- Interview prep, PRD area 4: the launch question set for frontend and software
-- engineering (research R7 starts with a curated set; user reports join later).
--
-- 82 questions across behavioral (STAR), JavaScript, React, web fundamentals,
-- frontend system design and leadership. Every row is source_kind = 'curated' and carries
-- a source note that the UI shows under the question. Idempotent: re-running skips slugs
-- that already exist.

INSERT INTO public.questions
  (slug, role, topic, level, stages, company_types, most_asked, prompt, framework_hint, source_kind, source_note)
